import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function AdminProductsPage() {
  const products = await getProducts()

  // Inline Server Action: trigger a background refresh of the catalog.
  //
  // `revalidateTag("products", "max")` marks the cached catalog as stale and
  // uses stale-while-revalidate semantics — the admin's submit returns
  // immediately, the (briefly) stale list keeps showing, and fresh ERP/PIM data
  // is fetched in the background the next time a view using the `"products"` tag
  // is visited. This refreshes every dependent view, not just this page.
  //
  // We deliberately avoid `updateTag` here: that's for read-your-own-writes and
  // would block on a fresh recompute, which a multi-thousand-SKU sync makes slow
  // and unnecessary for a catalog that tolerates eventual consistency.
  async function syncCatalog() {
    'use server'
    // Kick off the upstream sync job here (ERP/PIM → DB). It's expected to run
    // beyond this request; we don't block the admin on it completing.
    revalidateTag('products', 'max')
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

